class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        start=[1]
        end=[n]
        for i in range(2,math.ceil(math.sqrt(n))+1):
            if n%i==0:
                start.append(i)
                if i!=n//i:
                    end.append(n//i)
        start=sorted(set(start).union(set(end)))
        if k<=len(start):
            return start[k-1]
        else:
            return -1

class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        result = []
        i = 1
        while i*i <= n:
            if not n%i:
                if i*i != n:
                    result.append(i)
                k -= 1
                if not k:
                    return i
            i += 1
        return -1 if k > len(result) else n//result[-k]

class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        def kth_factor(n, k=0):
            mid = None
            i = 1
            while i*i <= n:
                if not n%i:
                    mid = i
                    k -= 1
                    if not k:
                        break
                i += 1
            return mid, -k

        mid, count = kth_factor(n)
        total = 2*count-(mid*mid == n)
        if k > total:
            return -1
        result = kth_factor(n, k if k <= count else total-(k-1))[0]
        return result if k <= count else n//result
